#!/usr/bin/env bash
# `make generate` owns every GENERATED file and section, and `make check-generated` refuses a tree in
# which one was edited by hand. Every case works in a copy of this tree committed to a throwaway
# repository, never in this checkout.
set -euo pipefail

kernel="$(cd "$(dirname "$0")/.." && pwd)"
root="$(mktemp -d)"
trap 'rm -rf "$root"' EXIT
tree="$root/tree"
mkdir -p "$tree"
(cd "$kernel" && git ls-files -z -co --exclude-standard \
	| xargs -0 sh -c 'for f; do [ -e "$f" ] && printf "%s\0" "$f"; done' sh \
	| xargs -0 cp -P --parents -t "$tree")
cd "$tree"
commit() { git add -A && git -c user.name=t -c user.email=t@example.invalid commit -qm "$1"; }
git init -q && commit 'the tree as it stands'
failures=0
fail() { echo "FAIL: $1"; [ -f "$root/out" ] && sed 's/^/    /' "$root/out" | head -20; failures=$((failures + 1)); }
composition=(apps/platformkit/COMPOSITION.development.md apps/platformkit/COMPOSITION.production.md
	apps/platformkit/COMPOSITION.development.json apps/platformkit/COMPOSITION.production.json)

if ! ${MAKE:-make} -s check-generated >"$root/out" 2>&1; then
	fail 'the tree as committed is not what make generate writes'
elif ${MAKE:-make} -s generate >"$root/out" 2>&1 && [ -z "$(git status --porcelain)" ]; then
	echo 'ok   make generate leaves the committed tree unchanged, twice'
else
	fail 'a second make generate changed the tree'
fi

for file in "${composition[@]}"; do
	if [ "$(git check-attr linguist-generated -- "$file")" != "$file: linguist-generated: true" ]; then
		fail "$file is not marked linguist-generated"
	fi
done
for file in "${composition[@]:0:2}"; do
	if [ "$(head -1 "$file")" != '<!-- Code generated by platformkit composition; DO NOT EDIT. -->' ]; then
		fail "$file does not begin with the generated-file marker"
	fi
done
echo 'ok   the composition documents carry their markers'

# One byte in each composition document, one figure in each generated section of the inventory, and
# one file name inside the generated merge groups.
for file in "${composition[@]}"; do sed -i '0,/a/s/a/A/' "$file"; done
sed -i -e 's/^\(| test rows | \)[0-9]*/\1999999/' \
       -e 's/^\(| behaviour | \)[0-9]*/\1999999/' \
       -e 's/^\(| `keep` | \)[0-9]*/\1999999/' \
       -e 's/autocommit_function_body_test\.go/an_authored_name_test.go/' \
       -e 's/^The verdict columns sum to [0-9]*/The verdict columns sum to 9999/' \
       -e 's/declares a ceiling of [0-9]*/declares a ceiling of 1/' tests/INVENTORY.md
commit 'hand edits'
if ${MAKE:-make} -s check-generated >"$root/out" 2>&1; then
	fail 'hand-edited generated files passed check-generated'
else
	for file in "${composition[@]}" tests/INVENTORY.md; do
		grep -q "^diff --git a/$file " "$root/out" || fail "the refusal does not name $file"
	done
	echo 'ok   a hand-edited generated file or section fails check-generated'
fi
git reset -q --hard HEAD~1

# The writer refuses a marker it cannot pair, a block it does not render and a block held twice,
# and leaves the document as it found it.
refuses() { # refuses <case name> <sed script>
	git checkout -q -- tests/INVENTORY.md
	sed -i "$2" tests/INVENTORY.md
	cp tests/INVENTORY.md "$root/before"
	local got=0
	PYTHONDONTWRITEBYTECODE=1 python3 scripts/inventory_figures.py >"$root/out" 2>&1 || got=$?
	if [ "$got" != 2 ] || ! cmp -s tests/INVENTORY.md "$root/before"; then
		fail "$1: exit $got, wanted 2 with the document unchanged"
	else
		echo "ok   $1 is refused and the document is unchanged"
	fi
}
refuses 'a BEGIN without its END' '0,/^<!-- END GENERATED -->$/{/^<!-- END GENERATED -->$/d}'
refuses 'a block the writer does not render' 's/inventory_figures.py go-test-ceiling -->/inventory_figures.py go-test-floor -->/'
refuses 'a block held twice' 's/inventory_figures.py go-test-ceiling -->/inventory_figures.py area-verdicts -->/'
refuses 'a block the document lacks' '/^<!-- BEGIN GENERATED: scripts\/inventory_figures.py go-test-ceiling -->$/,/^<!-- END GENERATED -->$/d'
git checkout -q -- tests/INVENTORY.md

[ "$failures" -eq 0 ] || { echo "$failures case(s) failed"; exit 1; }
echo 'generated files: all cases hold'
